package com.jamescornwell.seachartnavigator;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/** Launches a development RuneLite client with this plugin loaded. */
public class SeaChartNavigatorPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SeaChartNavigatorPlugin.class);
		RuneLite.main(args);
	}
}

package com.jamescornwell.seachartnavigator.ui;

import static org.junit.Assert.*;
import static org.mockito.AdditionalAnswers.delegatesTo;
import static org.mockito.Mockito.*;

import com.jamescornwell.seachartnavigator.HudVisibility;
import com.jamescornwell.seachartnavigator.SeaChartNavigatorConfig;
import com.jamescornwell.seachartnavigator.model.ChartingTask;
import com.jamescornwell.seachartnavigator.model.ChartingTaskType;
import com.jamescornwell.seachartnavigator.service.NavigationState;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class SeaChartNavigationOverlayTest
{
	@Test
	public void doesNotReadPlayerWhileLoadingEvenWithAnOldTarget()
	{
		Client client = mock(Client.class);
		when(client.getGameState()).thenReturn(GameState.LOADING);
		NavigationState state = new NavigationState();
		state.setTarget(new ChartingTask(1, "Test", ChartingTaskType.GENERIC, 1, new WorldPoint(100, 100, 0), 1));
		assertNoPlayerRead(client, state);
	}

	@Test
	public void doesNotReadPlayerWhenThereIsNoTarget()
	{
		Client client = mock(Client.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		assertNoPlayerRead(client, new NavigationState());
	}

	@Test
	public void exactLocationShowsNeutralMarkerWithoutReadingCamera()
	{
		Client client = clientAt(100, 100);
		SeaChartNavigationOverlay overlay = overlay(client, new WorldPoint(100, 100, 0));
		BufferedImage north = renderImage(overlay, "At location");
		when(client.getCameraYaw()).thenReturn(4096);
		BufferedImage west = renderImage(overlay, "At location");

		assertArrayEquals(pixels(north), pixels(west));
		verify(client, never()).getCameraYaw();
	}

	@Test
	public void nearbyTargetStillTracksCameraOnEveryRender()
	{
		Client client = clientAt(100, 100);
		SeaChartNavigationOverlay overlay = overlay(client, new WorldPoint(100, 105, 0));
		BufferedImage north = renderImage(overlay, "5 tiles away");
		when(client.getCameraYaw()).thenReturn(4096);
		BufferedImage west = renderImage(overlay, "5 tiles away");

		assertFalse(Arrays.equals(pixels(north), pixels(west)));
		verify(client, times(2)).getCameraYaw();
	}

	@Test
	public void leavingTargetRestoresDirectionAndLiveDistance()
	{
		Client client = clientAt(100, 100);
		SeaChartNavigationOverlay overlay = overlay(client, new WorldPoint(100, 100, 0));
		renderImage(overlay, "At location");
		when(client.getLocalPlayer().getLocalLocation()).thenReturn(new LocalPoint(64, 192, WorldView.TOPLEVEL));
		renderImage(overlay, "1 tile away");
		verify(client, times(1)).getCameraYaw();
	}

	private Client clientAt(int x, int y)
	{
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		WorldView worldView = mock(WorldView.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getTopLevelWorldView()).thenReturn(worldView);
		when(player.getWorldView()).thenReturn(worldView);
		when(player.getLocalLocation()).thenReturn(new LocalPoint(64, 64, WorldView.TOPLEVEL));
		when(worldView.isTopLevel()).thenReturn(true);
		when(worldView.getBaseX()).thenReturn(x);
		when(worldView.getBaseY()).thenReturn(y);
		return client;
	}

	private SeaChartNavigationOverlay overlay(Client client, WorldPoint target)
	{
		NavigationState state = new NavigationState();
		state.setTarget(new ChartingTask(1, "Test", ChartingTaskType.GENERIC, 1, target, 1));
		return new SeaChartNavigationOverlay(client, alwaysVisibleConfig(), state);
	}

	private BufferedImage renderImage(SeaChartNavigationOverlay overlay, String expectedDistance)
	{
		BufferedImage image = new BufferedImage(500, 100, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = mock(Graphics2D.class, delegatesTo(image.createGraphics()));
		try
		{
			assertNotNull(overlay.render(graphics));
			verify(graphics).drawString(eq(expectedDistance), anyInt(), anyInt());
			return image;
		}
		finally
		{
			graphics.dispose();
		}
	}

	private int[] pixels(BufferedImage image)
	{
		return image.getRGB(0, 0, image.getWidth(), image.getHeight(), null, 0, image.getWidth());
	}

	private SeaChartNavigatorConfig alwaysVisibleConfig()
	{
		return new SeaChartNavigatorConfig()
		{
			@Override
			public HudVisibility hudVisibility()
			{
				return HudVisibility.ALWAYS;
			}
		};
	}

	private void assertNoPlayerRead(Client client, NavigationState state)
	{
		SeaChartNavigationOverlay overlay = new SeaChartNavigationOverlay(client, alwaysVisibleConfig(), state);
		Graphics2D graphics = new BufferedImage(500, 100, BufferedImage.TYPE_INT_ARGB).createGraphics();
		try
		{
			assertNull(overlay.render(graphics));
			verify(client, never()).getLocalPlayer();
		}
		finally
		{
			graphics.dispose();
		}
	}
}

package com.jamescornwell.seachartnavigator.service;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.jamescornwell.seachartnavigator.model.ChartingTask;
import com.jamescornwell.seachartnavigator.model.ChartingTaskType;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

public class ChartingTaskRepositoryTest
{
	@Test
	public void loadsEveryBundledChartingTask()
	{
		ChartingTaskRepository repository = new ChartingTaskRepository();

		assertEquals(358, repository.getTasks().size());
		assertTrue(repository.isCompletionVarbit(18574));
		assertNotNull(repository.getTasks().get(0).getLocation());
	}

	@Test
	public void everyBundledTaskHasValidUniqueMetadata()
	{
		ChartingTaskRepository repository = new ChartingTaskRepository();
		Set<Integer> ids = new HashSet<>();
		Set<Integer> varbits = new HashSet<>();
		Set<ChartingTaskType> types = EnumSet.noneOf(ChartingTaskType.class);
		for (ChartingTask task : repository.getTasks())
		{
			assertTrue("Duplicate task ID: " + task.getId(), ids.add(task.getId()));
			assertTrue("Duplicate completion varbit: " + task.getCompletionVarbit(),
				varbits.add(task.getCompletionVarbit()));
			assertTrue(task.getCompletionVarbit() > 0);
			assertTrue(repository.isCompletionVarbit(task.getCompletionVarbit()));
			assertTrue(!task.getTitle().trim().isEmpty());
			assertTrue(task.getRequiredSailingLevel() >= 1 && task.getRequiredSailingLevel() <= 99);
			assertTrue(task.getLocation().getX() > 0 && task.getLocation().getY() > 0);
			assertEquals(0, task.getLocation().getPlane());
			types.add(task.getType());
		}
		assertEquals(EnumSet.allOf(ChartingTaskType.class), types);
	}
}

package com.jamescornwell.seachartnavigator.service;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertNull;

import com.jamescornwell.seachartnavigator.model.ChartingTask;
import com.jamescornwell.seachartnavigator.model.ChartingTaskType;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import net.runelite.api.coords.WorldPoint;

public class TargetSelectorTest
{
	private final TargetSelector selector = new TargetSelector();

	@Test
	public void selectsTheClosestEligibleTask()
	{
		ChartingTask near = task(1, 101, 105, 1);
		ChartingTask far = task(2, 160, 160, 1);
		ChartingTask locked = task(3, 100, 101, 99);
		List<ChartingTask> tasks = Arrays.asList(near, far, locked);

		ChartingTask selected = selector.selectClosest(tasks, new WorldPoint(100, 100, 0), task -> task.hasSailingLevel(20));

		assertSame(near, selected);
	}

	@Test
	public void calculatesChebyshevTileDistance()
	{
		assertEquals(8, selector.distance(new WorldPoint(100, 100, 0), new WorldPoint(108, 103, 0)));
	}

	@Test
	public void selectsANewTargetAfterThePlayerMoves()
	{
		ChartingTask west = task(1, 100, 100, 1);
		ChartingTask east = task(2, 120, 100, 1);
		List<ChartingTask> tasks = Arrays.asList(west, east);
		assertSame(west, selector.selectClosest(tasks, new WorldPoint(101, 100, 0), task -> true));
		assertSame(east, selector.selectClosest(tasks, new WorldPoint(119, 100, 0), task -> true));
	}

	@Test
	public void keepsDatasetOrderForEqualDistances()
	{
		ChartingTask first = task(1, 95, 100, 1);
		ChartingTask second = task(2, 105, 100, 1);
		assertSame(first, selector.selectClosest(Arrays.asList(first, second),
			new WorldPoint(100, 100, 0), task -> true));
	}

	@Test
	public void noEligibleTasksOrNoPositionReturnsNoTarget()
	{
		List<ChartingTask> tasks = Collections.singletonList(task(1, 100, 100, 20));
		WorldPoint player = new WorldPoint(100, 100, 0);
		assertNull(selector.selectClosest(tasks, player, task -> task.hasSailingLevel(19)));
		assertNull(selector.selectClosest(tasks, null, task -> true));
		assertNull(selector.selectClosest(Collections.emptyList(), player, task -> true));
	}

	@Test
	public void exactRequiredLevelUnlocksTheTask()
	{
		ChartingTask target = task(1, 100, 100, 20);
		assertSame(target, selector.selectClosest(Collections.singletonList(target),
			new WorldPoint(100, 100, 0), task -> task.hasSailingLevel(20)));
	}

	private ChartingTask task(int id, int x, int y, int level)
	{
		return new ChartingTask(id, "Task " + id, ChartingTaskType.GENERIC, id, new WorldPoint(x, y, 0), level);
	}
}

package com.jamescornwell.seachartnavigator.service;

import static org.junit.Assert.assertEquals;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class NavigationMathTest
{
	@Test
	public void northIsStraightAheadWhenTheCameraFacesNorth()
	{
		assertEquals(
			0.0,
			NavigationMath.cameraRelativeAngle(new WorldPoint(100, 100, 0), new WorldPoint(100, 101, 0), 0),
			0.0001
		);
	}

	@Test
	public void eastIsStraightAheadWhenTheCameraFacesEast()
	{
		assertEquals(
			0.0,
			NavigationMath.cameraRelativeAngle(new WorldPoint(100, 100, 0), new WorldPoint(101, 100, 0), 12288),
			0.0001
		);
	}

	@Test
	public void northIsToTheRightWhenTheCameraFacesWest()
	{
		assertEquals(
			Math.PI / 2.0,
			NavigationMath.cameraRelativeAngle(new WorldPoint(100, 100, 0), new WorldPoint(100, 101, 0), 4096),
			0.0001
		);
	}

	@Test
	public void yawUsesTheFullFourteenBitAngleRange()
	{
		assertEquals(
			0.0,
			NavigationMath.cameraRelativeAngle(new WorldPoint(100, 100, 0), new WorldPoint(100, 101, 0), 16384),
			0.0001
		);
	}

	@Test
	public void everyCameraYawRotatesNorthAndEastBearingsOncePerTurn()
	{
		WorldPoint origin = new WorldPoint(100, 100, 0);
		WorldPoint north = new WorldPoint(100, 101, 0);
		WorldPoint east = new WorldPoint(101, 100, 0);
		for (int yaw = 0; yaw < 16384; yaw++)
		{
			double radians = yaw * Math.PI * 2.0 / 16384.0;
			double northAngle = NavigationMath.cameraRelativeAngle(origin, north, yaw);
			double eastAngle = NavigationMath.cameraRelativeAngle(origin, east, yaw);
			assertEquals(Math.sin(radians), Math.sin(northAngle), 0.000001);
			assertEquals(Math.cos(radians), Math.cos(northAngle), 0.000001);
			assertEquals(Math.cos(radians), Math.sin(eastAngle), 0.000001);
			assertEquals(-Math.sin(radians), Math.cos(eastAngle), 0.000001);
			assertEquals(northAngle, NavigationMath.cameraRelativeAngle(origin, north, yaw + 16384), 0.000001);
			assertEquals(northAngle, NavigationMath.cameraRelativeAngle(origin, north, yaw - 16384), 0.000001);
		}
	}

	@Test
	public void calculatesChebyshevTileDistance()
	{
		assertEquals(8, NavigationMath.tileDistance(new WorldPoint(100, 100, 0), new WorldPoint(108, 103, 0)));
	}
}

package com.jamescornwell.seachartnavigator.service;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import net.runelite.api.Client;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

public class SailingStateTest
{
	private final Client client = mock(Client.class);
	private final Player player = mock(Player.class);
	private final WorldView topLevel = mock(WorldView.class);
	private final WorldView boatView = mock(WorldView.class);
	private final WorldEntity boat = mock(WorldEntity.class);
	private final LocalPoint local = new LocalPoint(10 * 128 + 64, 20 * 128 + 64, WorldView.TOPLEVEL);

	@Before
	public void setUp()
	{
		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getTopLevelWorldView()).thenReturn(topLevel);
		when(client.getWorldView(WorldView.TOPLEVEL)).thenReturn(topLevel);
		when(player.getWorldView()).thenReturn(topLevel);
		when(player.getLocalLocation()).thenReturn(local);
		when(topLevel.isTopLevel()).thenReturn(true);
		when(topLevel.getBaseX()).thenReturn(3100);
		when(topLevel.getBaseY()).thenReturn(3200);
	}

	@Test
	public void resolvesOrdinaryWorldPosition()
	{
		assertEquals(new WorldPoint(3110, 3220, 0), SailingState.getTopLevelWorldPoint(client));
		assertFalse(SailingState.isSailing(client));
	}

	@Test
	public void missingPlayerReturnsNoPosition()
	{
		when(client.getLocalPlayer()).thenReturn(null);
		assertNull(SailingState.getTopLevelWorldPoint(client));
		assertFalse(SailingState.isSailing(client));
	}

	@Test
	public void missingPlayerWorldViewReturnsNoPosition()
	{
		when(player.getWorldView()).thenReturn(null);
		assertNull(SailingState.getTopLevelWorldPoint(client));
		assertFalse(SailingState.isSailing(client));
	}

	@Test
	public void missingLocalPositionReturnsNoPosition()
	{
		when(player.getLocalLocation()).thenReturn(null);
		assertNull(SailingState.getTopLevelWorldPoint(client));
	}

	@Test
	public void missingTopLevelDuringBoatUnloadReturnsNoPosition()
	{
		when(player.getWorldView()).thenReturn(boatView);
		when(client.getTopLevelWorldView()).thenReturn(null);
		assertNull(SailingState.getTopLevelWorldPoint(client));
	}

	@Test
	public void resolvesBoatPositionInTheTopLevelWorld()
	{
		boardBoat();
		when(boat.transformToMainWorld(local)).thenReturn(new LocalPoint(50 * 128 + 64, 60 * 128 + 64, WorldView.TOPLEVEL));
		assertEquals(new WorldPoint(3150, 3260, 0), SailingState.getTopLevelWorldPoint(client));
		assertTrue(SailingState.isSailing(client));
		verify(boat).transformToMainWorld(local);
	}

	@Test
	public void missingBoatEntityReturnsNoPosition()
	{
		boardBoat();
		when(topLevel.worldEntities().byIndex(5)).thenReturn(null);
		assertNull(SailingState.getTopLevelWorldPoint(client));
	}

	@Test
	public void unavailableBoatTransformReturnsNoPosition()
	{
		boardBoat();
		when(boat.transformToMainWorld(local)).thenReturn(null);
		assertNull(SailingState.getTopLevelWorldPoint(client));
	}

	@SuppressWarnings("unchecked")
	private void boardBoat()
	{
		IndexedObjectSet<WorldEntity> entities = mock(IndexedObjectSet.class);
		doReturn(entities).when(topLevel).worldEntities();
		when(player.getWorldView()).thenReturn(boatView);
		when(boatView.getId()).thenReturn(5);
		when(entities.byIndex(5)).thenReturn(boat);
	}
}

package com.jamescornwell.seachartnavigator;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

import com.jamescornwell.seachartnavigator.model.ChartingTask;
import com.jamescornwell.seachartnavigator.model.ChartingTaskType;
import com.jamescornwell.seachartnavigator.service.ChartingTaskRepository;
import com.jamescornwell.seachartnavigator.service.NavigationState;
import com.jamescornwell.seachartnavigator.service.TargetSelector;
import com.jamescornwell.seachartnavigator.ui.SeaChartNavigationOverlay;
import java.util.ArrayDeque;
import java.util.Collections;
import java.util.Queue;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.HintArrowType;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.Notification;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.mockito.Spy;

public class SeaChartNavigatorLifecycleTest
{
	@Mock private Client client;
	@Mock private ClientThread clientThread;
	@Mock private SeaChartNavigatorConfig config;
	@Mock private OverlayManager overlayManager;
	@Mock private SeaChartNavigationOverlay navigationOverlay;
	@Mock private WorldMapPointManager worldMapPointManager;
	@Mock private ChartingTaskRepository taskRepository;
	@Mock private Notifier notifier;
	@Mock private Player player;
	@Mock private WorldView worldView;
	@Spy private NavigationState navigationState = new NavigationState();
	@Spy private TargetSelector targetSelector = new TargetSelector();
	@InjectMocks private SeaChartNavigatorPlugin plugin;

	private final Queue<Runnable> callbacks = new ArrayDeque<>();
	private final ChartingTask target = new ChartingTask(1, "Test task", ChartingTaskType.GENERIC,
		18574, new WorldPoint(105, 100, 0), 1);
	private AutoCloseable mocks;
	private boolean onClientThread;
	private GameState gameState = GameState.LOGGED_IN;
	private int hintType = HintArrowType.NONE;
	private WorldPoint hintPoint;

	@Before
	public void setUp()
	{
		mocks = MockitoAnnotations.openMocks(this);
		when(config.navigatorEnabled()).thenReturn(true);
		when(config.showWorldMapPin()).thenReturn(true);
		when(config.useNativeHintArrow()).thenReturn(true);
		when(config.arrivalRadius()).thenReturn(8);
		when(config.targetNotifications()).thenReturn(Notification.OFF);
		when(config.arrivalNotifications()).thenReturn(Notification.OFF);
		when(taskRepository.getTasks()).thenReturn(Collections.singletonList(target));
		when(client.getGameState()).thenAnswer(invocation -> gameState);
		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getTopLevelWorldView()).thenReturn(worldView);
		when(client.getWorldView(anyInt())).thenReturn(worldView);
		when(client.getRealSkillLevel(Skill.SAILING)).thenReturn(99);
		when(player.getLocalLocation()).thenReturn(new LocalPoint(64, 64, WorldView.TOPLEVEL));
		when(player.getWorldView()).thenAnswer(invocation ->
		{
			requireClientThread();
			return worldView;
		});
		when(worldView.isTopLevel()).thenReturn(true);
		when(worldView.getBaseX()).thenReturn(100);
		when(worldView.getBaseY()).thenReturn(100);
		when(client.getHintArrowType()).thenAnswer(invocation -> hintType);
		when(client.getHintArrowPoint()).thenAnswer(invocation -> hintPoint);
		doAnswer(invocation ->
		{
			requireClientThread();
			hintType = HintArrowType.COORDINATE;
			hintPoint = invocation.getArgument(0);
			return null;
		}).when(client).setHintArrow(any(WorldPoint.class));
		doAnswer(invocation ->
		{
			requireClientThread();
			hintType = HintArrowType.NONE;
			hintPoint = null;
			return null;
		}).when(client).clearHintArrow();
		doAnswer(invocation ->
		{
			Runnable action = invocation.getArgument(0);
			if (onClientThread)
			{
				action.run();
			}
			else
			{
				callbacks.add(action);
			}
			return null;
		}).when(clientThread).invoke(any(Runnable.class));
		doAnswer(invocation ->
		{
			callbacks.add(invocation.getArgument(0));
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));
	}

	@After
	public void tearDown() throws Exception
	{
		mocks.close();
	}

	@Test
	public void settingsChangedOnSwingThreadAreDeferred() throws Exception
	{
		enable();
		clearInvocations(player);
		SwingUtilities.invokeAndWait(() -> plugin.onConfigChanged(configChanged()));
		verifyNoInteractions(player);
		drainCallbacks();
		assertSame(target, navigationState.getTarget());
		verify(player).getWorldView();
	}

	@Test
	public void shutdownOnSwingThreadClearsArrowOnClientThread() throws Exception
	{
		enable();
		SwingUtilities.invokeAndWait(plugin::shutDown);
		assertEquals(target.getLocation(), hintPoint);
		drainCallbacks();
		assertNull(navigationState.getTarget());
		assertEquals(HintArrowType.NONE, hintType);
	}

	@Test
	public void pendingStartupCannotRecreateNavigationAfterDisable()
	{
		plugin.startUp();
		plugin.shutDown();
		drainCallbacks();
		assertNull(navigationState.getTarget());
		verify(client, never()).setHintArrow(any(WorldPoint.class));
		verify(worldMapPointManager, never()).add(any());
	}

	@Test
	public void callbacksFromOldSessionCannotAffectQuickReenable()
	{
		plugin.startUp();
		plugin.onConfigChanged(configChanged());
		plugin.shutDown();
		plugin.startUp();
		drainCallbacks();
		assertSame(target, navigationState.getTarget());
		verify(client, times(1)).setHintArrow(target.getLocation());
		verify(worldMapPointManager, times(1)).add(any());
	}

	@Test
	public void queuedConfigurationChangeIsDiscardedAfterDisable()
	{
		enable();
		clearInvocations(player);
		plugin.onConfigChanged(configChanged());
		plugin.shutDown();
		drainCallbacks();
		verifyNoInteractions(player);
		assertNull(navigationState.getTarget());
	}

	@Test
	public void existingNpcArrowIsPreservedAndNavigationResumesWhenItClears()
	{
		hintType = HintArrowType.NPC;
		enable();
		assertSame(target, navigationState.getTarget());
		assertEquals(HintArrowType.NPC, hintType);
		verify(client, never()).setHintArrow(any(WorldPoint.class));
		hintType = HintArrowType.NONE;
		tick();
		assertEquals(target.getLocation(), hintPoint);
	}

	@Test
	public void shutdownPreservesAReplacementCoordinateArrow()
	{
		enable();
		WorldPoint otherTarget = new WorldPoint(200, 200, 0);
		hintPoint = otherTarget;
		plugin.shutDown();
		drainCallbacks();
		assertEquals(otherTarget, hintPoint);
		verify(client, never()).clearHintArrow();
	}

	@Test
	public void settingsRefreshDoesNotOverwriteAnotherPluginsArrow()
	{
		enable();
		hintType = HintArrowType.NPC;
		hintPoint = null;
		plugin.onConfigChanged(configChanged());
		drainCallbacks();
		assertEquals(HintArrowType.NPC, hintType);
		plugin.shutDown();
		drainCallbacks();
		assertEquals(HintArrowType.NPC, hintType);
